def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = np.full((3, 3), bg, dtype=int)
    out[1, 1] = 5
    emit(out, "Allocate the 3x3 output: the colour-5 marker of every fragment will be aligned on the centre cell.")
    for y in range(H):
        for x in range(W):
            if g[y, x] != 5:
                continue
            # 3x3 window centred on this 5 -> output coordinates (dy+1, dx+1)
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W:
                        c = g[yy, xx]
                        if c != bg and c != 5:
                            out[dy + 1, dx + 1] = c
            emit(out, f"Stamp the fragment whose 5 is at ({y},{x}): slide it so its 5 sits on the centre and copy its coloured cells.")
    emit(out, "All fragments overlaid around the shared centre 5; uncovered cells stay background.")
    return out
